import{_ as a,o as r,c as s,a4 as n}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0060 — Balayage des fichiers orphelins par l'ordonnanceur","description":"Extrait de docs/adr/0060-balayage-des-fichiers-orphelins.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0060 — Balayage des fichiers orphelins par l'ordonnanceur","description":"Extrait de docs/adr/0060-balayage-des-fichiers-orphelins.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0060-balayage-des-fichiers-orphelins.md","filePath":"developpeurs/adr/0060-balayage-des-fichiers-orphelins.md"}`),t={name:"developpeurs/adr/0060-balayage-des-fichiers-orphelins.md"};function i(o,e,d,l,u,c){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0060--balayage-des-fichiers-orphelins-par-lordonnanceur" tabindex="-1">ADR-0060 — Balayage des fichiers orphelins par l&#39;ordonnanceur <a class="header-anchor" href="#adr-0060--balayage-des-fichiers-orphelins-par-lordonnanceur" aria-label="Permalink to &quot;ADR-0060 — Balayage des fichiers orphelins par l&#39;ordonnanceur {#adr-0060--balayage-des-fichiers-orphelins-par-lordonnanceur}&quot;">​</a></h1><p><strong>Date :</strong> 28 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-7 ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0058-cloture-d-une-organisation">ADR-0058</a> (clôture d&#39;une organisation), dont il est le filet <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (écart reconnu : « Supprimer une organisation efface ses lignes <code>media_assets</code> en cascade, mais laisse les octets sur le disque ») et, pour les fichiers personnels, le même écart relevé à l&#39;ADR-0038</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Les fichiers personnels (<code>PERSONAL_FILE_ROOT</code>) et les médias (<code>MEDIA_ROOT</code>) sont rangés sur disque sous une clé qui est l&#39;empreinte SHA-256 de l&#39;organisation et de l&#39;identifiant du fichier (<code>storage_key</code>, ADR-0017). Leurs lignes (<code>personal_files</code>, <code>media_assets</code>, <code>media_captions</code>) dépendent de l&#39;organisation par <code>ON DELETE CASCADE</code>.</p><p>Aucune route ne supprime une organisation. Une suppression faite hors de l&#39;application (commande SQL, nettoyage d&#39;une base, restauration partielle) efface donc les lignes, mais laisse les octets sur le disque. Plus rien ne les désigne, et plus rien ne peut les effacer. Pour les fichiers personnels, ce sont des données personnelles conservées sans finalité.</p><p>L&#39;audit proposait deux voies : une commande de clôture d&#39;organisation, ou un balayage des orphelins.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Une tâche d&#39;ordonnanceur, pas un bouton.</strong> <code>orphan_file_sweep</code> tourne une fois par jour, en portée globale, en dernière position de la passe. Aucune route ne l&#39;expose, et aucune n&#39;est prévue.</li><li><strong>Un fichier est orphelin quand aucune ligne ne le désigne.</strong> L&#39;empreinte interdit de retrouver l&#39;organisation à partir du fichier : on ne peut pas tester « son organisation n&#39;existe plus ». On teste donc qu&#39;aucune ligne de <code>personal_files</code> (dépôt des fichiers personnels), de <code>media_assets</code> ou de <code>media_captions</code> (dépôt des médias) ne produit cette empreinte. Le calcul est fait par PostgreSQL (<code>sha256(organization_id::text || &#39;:&#39; || id::text)</code>), <strong>par lot</strong> : une requête par table et par répertoire de premier niveau (un 256e du dépôt), jamais une par fichier. Ce critère couvre exactement le cas d&#39;une organisation supprimée, et un fichier qu&#39;une ligne désigne n&#39;est jamais touché. <strong>Aucun fichier d&#39;une organisation vivante ne peut donc être effacé.</strong></li><li><strong>Deux temps : la quarantaine, puis l&#39;effacement.</strong> Un orphelin n&#39;est jamais effacé au premier passage. Il est déplacé sous <code>.quarantaine/</code> à la racine du dépôt, et daté du jour. Il n&#39;est effacé qu&#39;une fois le <strong>délai de grâce</strong> écoulé <strong>depuis sa mise en quarantaine</strong>. Si une ligne le désigne de nouveau entre-temps (sauvegarde de la base restaurée après une suppression par erreur), il est remis à sa place. La date d&#39;écriture d&#39;origine ne peut pas servir de point de départ : un fichier écrit il y a deux ans et devenu orphelin hier partirait aussitôt.</li><li><strong>Le délai de grâce est un réglage d&#39;instance</strong> : <code>ORPHAN_FILE_GRACE_DAYS</code>, 30 jours par défaut, entre 1 et 3650. Une valeur hors bornes ou illisible (<code>30 j</code>) empêche l&#39;API et l&#39;ordonnanceur de démarrer.</li><li><strong>Un fichier récent n&#39;est pas regardé.</strong> Un fichier écrit depuis moins d&#39;une heure peut appartenir à une requête en cours, dont la ligne n&#39;est pas encore visible (<code>RECENT_WRITE_AGE</code>).</li><li><strong>Le balayage ne touche qu&#39;à ce que le Core a écrit.</strong> Seuls les fichiers de la forme exacte d&#39;une clé (<code>ab/cd/&lt;64 hexadécimaux&gt;</code>, rangés sous leur propre préfixe) ou de son temporaire <code>.part</code> sont examinés. <code>.televersements/</code> (temporaires de la médiathèque, ADR-0044) garde son propre balayage.</li><li><strong>Un dépôt appartient à une base.</strong> Le premier passage pose une marque <code>.proprietaire</code> à la racine de chaque dépôt, avec le nom et l&#39;identifiant interne de la base. Un dépôt marqué par une autre base n&#39;est pas balayé, et la ligne de journal le dit. Vues depuis une autre base, toutes les empreintes sont inconnues : sans cette marque, un volume partagé par deux instances, ou une base de recette branchée sur le dépôt d&#39;une autre, verrait tous ses fichiers partir en quarantaine.</li><li><strong>Le journal.</strong> La ligne de l&#39;ordonnanceur donne, par dépôt, le nombre de fichiers mis en quarantaine, restaurés, effacés et encore dans leur délai, et si la borne du passage (1 000 fichiers par étape) a été atteinte. Chaque effacement écrit en outre une ligne <code>fichier_orphelin_efface</code> (journal <code>teuthis.orphelins</code>), avec le dépôt et l&#39;empreinte : ni nom d&#39;origine, ni contenu, ni organisation.</li><li><strong>Un dépôt branché par l&#39;exploitant</strong> (objet-store, <code>install_personal_file_store</code>) qui ne fournit pas de balayage n&#39;est pas balayé, et la ligne de journal le signale. Les deux dépôts livrés en mémoire n&#39;ont rien à balayer.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Commande CLI de clôture d&#39;organisation seule</strong></td><td>Elle ne couvre que les suppressions faites par elle. Le constat vise aussi celles faites hors de l&#39;application. Le Product Owner garde les deux : la commande (<a href="/teuthis-cms-distribution/developpeurs/adr/0058-cloture-d-une-organisation">ADR-0058</a>) pour le cas normal, ce balayage comme filet.</td></tr><tr><td><strong>Bouton « purger les orphelins » dans le back-office</strong></td><td>Décider qui a le droit d&#39;effacer des fichiers de toute l&#39;instance n&#39;est pas une décision d&#39;interface (même raisonnement que les autres purges, notice §6.3).</td></tr><tr><td><strong>Journal des organisations supprimées (déclencheur SQL)</strong></td><td>Il faudrait une migration et un déclencheur, et il ne couvrirait ni les suppressions antérieures ni une base restaurée.</td></tr><tr><td><strong>Effacement direct, délai compté depuis la date d&#39;écriture</strong></td><td>Un vieux fichier devenu orphelin partirait au premier passage, sans laisser le temps de restaurer une sauvegarde.</td></tr><tr><td><strong>Index sur l&#39;empreinte</strong></td><td>Une tâche quotidienne, des lots d&#39;un 256e du dépôt : à mesurer avant d&#39;ajouter une migration (ADR-0016).</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Les fichiers d&#39;une organisation supprimée hors application finissent effacés, fichiers personnels compris, sans geste manuel.</li><li>Une suppression par erreur reste rattrapable pendant le délai de grâce, fichiers compris, par la simple restauration de la base.</li><li>Aucune migration.</li></ul><p><strong>Négatives</strong></p><ul><li>Une table qui déposerait un jour des octets dans l&#39;un de ces dépôts <strong>doit</strong> s&#39;ajouter à <code>PERSONAL_FILE_TABLES</code> ou <code>MEDIA_TABLES</code> (<code>app/storage/orphans.py</code>), sans quoi ses fichiers seraient pris pour des orphelins. Le risque est borné par la quarantaine : rien n&#39;est effacé avant le délai de grâce.</li><li>Le balayage lit le dépôt entier chaque jour. Sans index sur l&#39;empreinte, chaque lot parcourt les tables concernées.</li><li>Une base recréée ou restaurée sur une autre instance PostgreSQL change d&#39;identifiant : le balayage se refuse jusqu&#39;à ce que l&#39;exploitant retire la marque <code>.proprietaire</code>. C&#39;est voulu : c&#39;est le moment où l&#39;on ne veut rien effacer sans avoir regardé.</li><li>Un fichier en quarantaine n&#39;est plus servi : si sa ligne n&#39;a disparu que le temps d&#39;une restauration, il revient au passage suivant, pas avant.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Tâche <code>orphan_file_sweep</code> (<code>app/scheduler/tasks.py</code>, <code>app/storage/orphans.py</code>). Preuve : <code>tests/test_balayage_des_fichiers_orphelins.py</code>.</li><li>[x] Réglage <code>ORPHAN_FILE_GRACE_DAYS</code>, validé au démarrage. Preuve : <code>test_le_delai_de_grace_est_valide_au_demarrage</code>.</li><li>[x] Notice d&#39;exploitation, §6.3 et §6.8.</li></ul>',17)])])}const h=a(t,[["render",i]]);export{g as __pageData,h as default};
